The fault is in ts-config-service's database connection handling. It has one root cause, and the errors travel up the call chain to the dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-config-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE level NOT IN ('INFO','DEBUG') AND service_name='ts-config-service' GROUP BY 1,2,3 ORDER BY c DESC", "claim": "Config service logs JDBC connection acquisition failures, Hikari timeouts and communications link failures during the incident."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-config-service' AND span_name IN ('SELECT Config','ConfigRepository.findByName','GET /api/v1/configservice/configs/{configName}') GROUP BY ALL", "claim": "Config's SELECT Config spans all error after about 30s, versus 3.5ms p95 in normal traffic."},
        {"kind": "metric", "sql": "SELECT p, service_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-config-service' GROUP BY ALL ORDER BY 2,1", "claim": "Config-service p95 rises from 3.5ms normal to about 30012ms abnormal, with 194 spans in abnormal period."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-config-service", "to": "ts-seat-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Seat-service left_tickets server spans fail with about 60s latency, waiting on config-service calls."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Travel-service trips/left server spans error with about 60s latency; client calls to seat time out."}]},
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Travel2-service trips/left server spans error with about 60s latency; client calls time out."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Route-plan server spans error after about 60s, with client POST calls to travel services timing out."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Route-plan server spans error after about 60s, consistent with timeouts on travel2 calls."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, attr_status_code s, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL", "claim": "Travel-plan server spans error after about 60s, with client calls to route-plan timing out."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC", "claim": "Dashboard travel and travelplan routes take about 20s p95 in abnormal period, versus under 60ms normally."}]}
